/// <summary>
///    Finds the specified record in the <c>KCS_KBVClassTable</c> table.
/// </summary>
/// <param name="_KCS_KBVClassID">
///    The record ID of the <c>KCS_KBVClassTable</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>KCS_KBVClassTable</c> table; otherwise, an empty record.
/// </returns>
public static KCS_KBVClassTable find(   KCS_KBVClassID  _KCS_KBVClassID,
                                        boolean         _forUpdate = false)
{
    KCS_KBVClassTable record;

    record.selectForUpdate(_forUpdate);

    if(_KCS_KBVClassID)
    {
        select firstonly record
        index hint KCS_KBVClassIDIdx
        where record.KCS_KBVClassID == _KCS_KBVClassID;
    }

    return record;
}

/// <summary>
///    Finds the specified record in the <c>KCS_KBVClassTable</c> table.
/// </summary>
/// <param name="_KCS_KBVClassID">
///    The record ID of the <c>KCS_KBVRelations</c> record to find.
/// </param>
/// <returns>
///    true if record in the <c>KCS_KBVClassTable</c> table exists
/// </returns>
public static boolean exist(KCS_KBVClassID   _KCS_KBVClassID)
{
    return      _KCS_KBVClassID
            &&  (   select firstonly KCS_KBVClassTable
                    index hint KCS_KBVClassIDIdx
                    where KCS_KBVClassTable.KCS_KBVClassID == _KCS_KBVClassID).Recid != 0;
}

[SysClientCacheDataMethodAttribute(true)]
display NDX_KBVClassTypeIdLang displayKCS_KBVClassIDLanguage(LanguageId _languageId = CompanyInfo::languageId())
{
    NDX_KBVClassTypeIdLang  retVal;

    retVal = NDX_KBVClassTableLang::getLanguageTypeId(this.KCS_KBVClassID, _languageId);

    if(!retVal)
    {
        retVal = this.KCS_KBVClassID;
    }

    return retVal;
}
